      {
        "step": "Find held deleted files",
        "hypothesis": "A process is still holding a handle to the 70GB log file that was deleted, preventing the OS from reclaiming the blocks.",
        "how_to_check": "lsof +L1 | grep '/data' OR lsof -nP | grep '(deleted)'"
      },
      {
        "step": "Analyze disk growth source",
        "hypothesis": "The current growth rate is driven by a specific directory or application log.",
        "how_to_check": "du -xh --max-depth=2 /data | sort -h | tail"
      },
      {
        "step": "Verify growth trend",
        "hypothesis": "The growth is a steady linear increase rather than a one-off spike.",
        "how_to_check": "predict_linear(node_filesystem_avail_bytes{mountpoint='/data'}[6h], 4*3600)"
      }
    ],
    "root_cause_hypotheses": [
      "Deleted files are being held open by a running process (likely the application that owned the 70GB log), preventing space reclamation.",
      "Runaway application logging or data generation on /data."
